440	/* 每分钟调用一次（由 PET_EVT_TIME_TICK / PET_TIME_TICK_MS timer 驱动）。
441	 * 衰减速率按 PET.txt 规格（每小时），用整数分钟累计：每分钟累加分子，
442	 * 满 60 分钟合一小时落地一次，避免"每秒/tick 直接改"过快。 */
443	static void pet_update_attrs_tick(void)
444	{
445	    /* 静态分钟累计器 */
446	    static int acc_hunger = 0, acc_energy = 0, acc_happy = 0, acc_health = 0,
447	               acc_sleep = 0;
448	
449	    int hunger_rate = 1;  /* 猫饥饿速率 */
450	
451	    acc_hunger += hunger_rate;
452	    acc_energy += PET_ENERGY_DECAY;
453	    acc_happy  += PET_HAPPINESS_DECAY;
454	    if (g_state == PET_STATE_SLEEP)
455	        acc_sleep += PET_ENERGY_SLEEP_RECOVER;
456	
457	    if (acc_hunger >= 60) { g_pet.attrs.hunger = clamp(g_pet.attrs.hunger + 1, 0, 100); acc_hunger -= 60; }
458	    if (acc_energy >= 120) { g_pet.attrs.energy = clamp(g_pet.attrs.energy - 1, 0, 100); acc_energy -= 120; }
459	    if (acc_happy >= 600) { g_pet.attrs.happiness = clamp(g_pet.attrs.happiness - 3, 0, 100); acc_happy -= 600; }
460	    if (acc_sleep >= 3) { g_pet.attrs.energy = clamp(g_pet.attrs.energy + 1, 0, 100); acc_sleep -= 3; }
461	
462	    /* 健康间接衰减：hunger<20 每分钟 -1/60（每小时 -1） */
463	    if (g_pet.attrs.hunger < 20)
464	    {
465	        acc_health += 1;
466	        if (acc_health >= 60)
467	        {
468	            g_pet.attrs.health = clamp(g_pet.attrs.health - 1, PET_HEALTH_FLOOR, 100);
469	            acc_health -= 60;
470	        }
471	    }
472	
473	    g_pet.last_update = time(NULL);
474	}
