480	static dm_pet_state_t pet_next_state(void)
481	{
482	    int h = get_hour();
483	
484	    /* 睡觉中：天亮 + 精力恢复够 → 自然醒（解决睡眠死锁，PET.txt §五时间联动） */
485	    if (g_state == PET_STATE_SLEEP)
486	    {
487	        if (h >= PET_WAKE_HOUR_START && h < PET_WAKE_HOUR_END &&
488	            g_pet.attrs.energy >= PET_WAKE_ENERGY_MIN)
489	            return PET_STATE_IDLE;
490	        /* 否则继续睡 */
491	        return PET_STATE_SLEEP;
492	    }
493	
494	    /* 深夜强制睡觉 */
495	    if (h >= 0 && h < 6)
496	        return PET_STATE_SLEEP;
497	
498	    /* 精力不足 → 困倦过渡（先 SLEEPY 再 SLEEP） */
499	    if (g_pet.attrs.energy < 25 && g_state != PET_STATE_SLEEPY &&
500	        g_state != PET_STATE_SLEEP)
501	        return PET_STATE_SLEEPY;
502	
503	    /* 精力耗尽 → 强制睡觉 */
504	    if (g_pet.attrs.energy < 10)
505	        return PET_STATE_SLEEP;
506	
507	    /* 饥饿 */
508	    if (g_pet.attrs.hunger > 80 && g_state != PET_STATE_EAT)
509	        return PET_STATE_HUNGRY;
510	
511	    /* 快乐极低 */
512	    if (g_pet.attrs.happiness < 20 && g_state != PET_STATE_SAD)
513	        return PET_STATE_SAD;
514	
515	    return PET_STATE_IDLE;
516	}
