523	static void pet_transition_to(dm_pet_state_t new_state, const char *why)
524	{
525	    dm_pet_state_t old = g_state;
526	    if (new_state == old)
527	    {
528	        pet_select_behavior();
529	        return;
530	    }
531	    g_state = new_state;
532	    pet_apply_state_effects();
533	    pet_select_behavior();
