543	
544	    /* 进入饥饿状态 → 显示可点击喂食提示（PET.txt §8） */
545	    if (new_state == PET_STATE_HUNGRY)
546	        pet_show_hunger_alert();
547	    else
548	        pet_hide_hunger_alert();
549	}
