575	static const pet_behavior_t *pick_from_pool(const pet_behavior_t *pool,
576	                                            int count)
577	{
578	    int total = 0;
579	    for (int i = 0; i < count; i++)
580	        total += pool[i].weight;
581	    if (total <= 0) return &pool[0];
582	
583	    int r = rand() % total;
584	    for (int i = 0; i < count; i++)
585	    {
586	        r -= pool[i].weight;
587	        if (r < 0) return &pool[i];
588	    }
589	    return &pool[count - 1];
590	}
