static void settings_pet_name_cb(lv_event_t *e)
{
    (void)e;
    const dm_pet_data_t *pd = dm_pet_get_data();
    if (!pd) return;

    /* 在当前 subpage overlay 上创建全屏遮罩（和 WiFi 密码输入同模式）
     * 不能直接在 settings scrollable card 上建 textarea+keyboard——
     * LVGL 9 键盘弹出时布局计算会崩 */
    lv_obj_t *subpage_overlay = lv_obj_get_parent(lv_event_get_current_target(e));
    /* 往上找到 subpage overlay（FLOATING 的全屏容器） */
    while (subpage_overlay && !lv_obj_has_flag(subpage_overlay, LV_OBJ_FLAG_FLOATING))
        subpage_overlay = lv_obj_get_parent(subpage_overlay);
    if (!subpage_overlay) return;

    lv_obj_t *overlay = lv_obj_create(subpage_overlay);
    lv_obj_set_size(overlay, LV_PCT(100), LV_PCT(100));
    lv_obj_set_style_bg_color(overlay, lv_color_hex(0x000000), 0);
    lv_obj_set_style_bg_opa(overlay, LV_OPA_60, 0);
    lv_obj_set_style_border_width(overlay, 0, 0);
    lv_obj_set_style_pad_all(overlay, 0, 0);
    lv_obj_clear_flag(overlay, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_add_flag(overlay, LV_OBJ_FLAG_FLOATING);
    lv_obj_add_flag(overlay, LV_OBJ_FLAG_CLICKABLE); /* 吞点击防穿透 */

    lv_obj_t *ta = lv_textarea_create(overlay);
    lv_obj_set_size(ta, DM(260), DM(44));
    lv_obj_align(ta, LV_ALIGN_TOP_MID, 0, DM(200));
    lv_textarea_set_one_line(ta, true);
    lv_textarea_set_max_length(ta, 15);
    lv_textarea_set_placeholder_text(ta, "输入名字（≤15字）");
    lv_textarea_set_text(ta, pd->name[0] ? pd->name : "旺财");
    lv_obj_set_style_text_font(ta, FONT_BODY, 0);
    lv_obj_set_style_bg_color(ta, lv_color_hex(0xFFFFFF), 0);
    lv_obj_set_style_radius(ta, DM(8), 0);
    lv_obj_set_style_border_width(ta, 1, 0);
    lv_obj_set_style_border_color(ta, lv_color_hex(0xCCCCCC), 0);
    lv_obj_add_flag(ta, LV_OBJ_FLAG_CLICKABLE);

    g_pet_name_kb = dm_kb_create(overlay, ta, settings_pet_name_ready_cb, NULL);
}

