{
    (void)e;
    dm_pet_type_t cur = dm_pet_get_type();
    dm_pet_type_t new_type = (cur == PET_TYPE_CAT) ? PET_TYPE_DOG : PET_TYPE_CAT;
    dm_pet_set_type(new_type);

    if (g_pet_type_lbl)
