    uint32_t base = (uint32_t)PET_SIZE * 256 / nw;
    float breathe = sinf(g_tick * 0.32f);
    uint32_t s = base + (uint32_t)(breathe * (float)base / 64); /* ±1.5% */
    lv_image_set_scale(g_body, s);
}

