/* ── 宠物在右下角留白区域内小范围缓慢漂移 ──
 * 约束矩形：健康栏上方 ~ 音乐控件下方，右侧区域
 * 不用 sqrt/走路帧，纯线性漂移，每8tick 算一次目标 */
g_bounce_off = 0;
if (g_state == PET_STATE_PLAY)
    g_bounce_off = (g_tick % 2) ? -10 : 10;
else if (g_state == PET_STATE_CELEBRATE)
    g_bounce_off = (g_tick % 2) ? -16 : 16;

/* 右下角约束矩形（相对于锁屏 overlay） */
{
    lv_coord_t sw = lv_display_get_horizontal_resolution(NULL);
    lv_coord_t sh = lv_display_get_vertical_resolution(NULL);
    /* 右半边：x 从屏幕中线到右边缘留边 */
    lv_coord_t zone_x1 = sw / 2 + DM(50);
    lv_coord_t zone_x2 = sw - PET_SIZE / 2 - DM(20);
    /* 纵向：健康圈上方到音乐卡下方，留出上下边距 */
    lv_coord_t zone_y1 = sh / 2 + DM(40);
    lv_coord_t zone_y2 = sh - PET_SIZE / 2 - DM(80);

    /* 每8tick 选一个新漂移目标 */
    if (g_tick % 8 == 0)
    {
        g_target_x = zone_x1 + (int)(rand() % (int)(zone_x2 - zone_x1 + 1));
        g_target_y = zone_y1 + (int)(rand() % (int)(zone_y2 - zone_y1 + 1));
    }

    /* 线性趋近（每tick 移1px，缓慢漂移感） */
    int dx = g_target_x - g_pet_x;
    int dy = g_target_y - g_pet_y;
    if (dx > 1) g_pet_x++; else if (dx < -1) g_pet_x--;
    if (dy > 1) g_pet_y++; else if (dy < -1) g_pet_y--;
    /* 朝向跟随 */
    if (dx > 1) g_face_right = true;
    else if (dx < -1) g_face_right = false;
}

