/* ── 宠物在右下角留白区域内左右走动 + 蹲坐交替 ──
 * 约束：只在 X 方向走，Y 固定；到边缘转身；蹲坐时不动 */
g_bounce_off = 0;
if (g_state == PET_STATE_PLAY)
    g_bounce_off = (g_tick % 2) ? -10 : 10;
else if (g_state == PET_STATE_CELEBRATE)
    g_bounce_off = (g_tick % 2) ? -16 : 16;

{
    lv_coord_t sw = lv_display_get_horizontal_resolution(NULL);
    lv_coord_t sh = lv_display_get_vertical_resolution(NULL);
    /* 左右走动范围 */
    lv_coord_t zone_x1 = sw / 2 + DM(50);
    lv_coord_t zone_x2 = sw - PET_SIZE / 2 - DM(20);
    /* Y 固定（健康栏上方，不上下移） */
    lv_coord_t zone_y  = sh - PET_SIZE / 2 - DM(80);
    g_pet_y = zone_y;

    /* 蹲坐/走动状态机：g_walk_pause >0 时蹲坐不动，=0 时走 */
    if (g_walk_pause > 0)
    {
        g_walk_pause--;          /* 蹲坐倒计时 */
    }
    else
    {
        /* 走动：每2tick 移2px（缓慢踱步） */
        if (g_tick % 2 == 0)
        {
            if (g_face_right)
                g_pet_x += 2;
            else
                g_pet_x -= 2;
        }
        /* 到边缘 → 转身 + 进入蹲坐 */
        if (g_pet_x >= zone_x2) { g_pet_x = zone_x2; g_face_right = false; g_walk_pause = 16 + rand() % 20; }
        if (g_pet_x <= zone_x1) { g_pet_x = zone_x1; g_face_right = true;  g_walk_pause = 16 + rand() % 20; }
    }
}

